/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { CrossCovarianceMatrix, CrossCovarianceMatrixNode, ExpectationMatrix, ExpectationMatrixNode, ImmutableDenseMatrix, MatAdd, MatMul, Matrix, MatrixSymbol, NormalDistribution, PSpace, RandomMatrixSymbol, RandomSymbol, Rational, SingleContinuousPSpace, Sym, Transpose, VarianceMatrix, VarianceMatrixNode, add, symbols } from '../../src';
import { sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.stats.symbolic_multivariate_probability", () => {
  it("CrossCovarianceMatrix(X, Y)", () => {
    const [X, k, Y] = symbols('X k Y');
    expect(sympyStr(CrossCovarianceMatrix(new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))))).toBe('CrossCovarianceMatrix(X, Y)');
  });
  it("CrossCovarianceMatrix(X, Y).shape", () => {
    const k = new Sym('k');
    expect(sympyMatches([k, k], '(k, k)')).toBe(true);
  });
  it("CrossCovarianceMatrix(X + Y, Z).expand()", () => {
    const [X, k, Y, Z] = symbols('X k Y Z');
    expect(sympyStr(new CrossCovarianceMatrixNode([MatAdd(new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), new RandomMatrixSymbol(Z, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))]).expand())).toBe('CrossCovarianceMatrix(X, Z) + CrossCovarianceMatrix(Y, Z)');
  });
  it("CrossCovarianceMatrix(A*X, Y).expand()", () => {
    const [k, X, Y] = symbols('k X Y');
    expect(sympyStr(new CrossCovarianceMatrixNode([MatMul(new MatrixSymbol('A', k, k), new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))]).expand())).toBe('A*CrossCovarianceMatrix(X, Y)');
  });
  it("CrossCovarianceMatrix(A*X, B.T*Y).expand()", () => {
    const [k, X, Y] = symbols('k X Y');
    expect(sympyStr(new CrossCovarianceMatrixNode([MatMul(new MatrixSymbol('A', k, k), new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), MatMul(Transpose(new MatrixSymbol('B', k, k)), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])))]).expand())).toBe('A*CrossCovarianceMatrix(X, Y)*B');
  });
  it("CrossCovarianceMatrix(A*X + B*Y, C.T*Z + D.T*W).expand()", () => {
    const [k, X, Y, Z, W] = symbols('k X Y Z W');
    expect(sympyStr(new CrossCovarianceMatrixNode([MatAdd(MatMul(new MatrixSymbol('A', k, k), new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), MatMul(new MatrixSymbol('B', k, k), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])))), MatAdd(MatMul(Transpose(new MatrixSymbol('C', k, k)), new RandomMatrixSymbol(Z, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), MatMul(Transpose(new MatrixSymbol('D', k, k)), new RandomMatrixSymbol(W, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))))]).expand())).toBe('A*CrossCovarianceMatrix(X, W)*D + A*CrossCovarianceMatrix(X, Z)*C + B*CrossCovarianceMatrix(Y, W)*D + B*CrossCovarianceMatrix(Y, Z)*C');
  });
  it("ExpectationMatrix(X)", () => {
    const [X, k] = symbols('X k');
    expect(sympyStr(ExpectationMatrix(new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))))).toBe('ExpectationMatrix(X)');
  });
  it("ExpectationMatrix(A*X).shape", () => {
    const k = new Sym('k');
    expect(sympyMatches([k, Rational.of(1n, 1n, { gcd: 1n })], '(k, 1)')).toBe(true);
  });
  it("ExpectationMatrix(A*X + B*Y).expand()", () => {
    const [k, X, Y] = symbols('k X Y');
    expect(sympyStr(new ExpectationMatrixNode([MatAdd(MatMul(new MatrixSymbol('A', k, k), new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), MatMul(new MatrixSymbol('B', k, k), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))))]).expand())).toBe('A*ExpectationMatrix(X) + B*ExpectationMatrix(Y)');
  });
  it("ExpectationMatrix((X + Y)*(X - Y).T).expand()", () => {
    const [X, k, Y] = symbols('X k Y');
    expect(sympyStr(new ExpectationMatrixNode([MatMul(MatAdd(new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), MatAdd(MatMul(Rational.of(-1n, 1n, { gcd: 1n }), Transpose(new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])))), Transpose(new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])))))]).expand())).toBe('ExpectationMatrix(X*X.T) - ExpectationMatrix(X*Y.T) + ExpectationMatrix(Y*X.T) - ExpectationMatrix(Y*Y.T)');
  });
  it("ExpectationMatrix(x1 + x2).doit()", () => {
    const [M11, N11, M12, N12, M21, N21, M22, N22] = symbols('M11 N11 M12 N12 M21 N21 M22 N22');
    expect(sympyStr(new ExpectationMatrixNode([ImmutableDenseMatrix(Matrix.of([[add(new RandomSymbol(M11, new SingleContinuousPSpace([M11, new NormalDistribution([Rational.of(1n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])])), new RandomSymbol(N11, new SingleContinuousPSpace([N11, new NormalDistribution([Rational.of(11n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])]))), add(new RandomSymbol(M12, new SingleContinuousPSpace([M12, new NormalDistribution([Rational.of(2n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])])), new RandomSymbol(N12, new SingleContinuousPSpace([N12, new NormalDistribution([Rational.of(12n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])])))], [add(new RandomSymbol(M21, new SingleContinuousPSpace([M21, new NormalDistribution([Rational.of(3n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])])), new RandomSymbol(N21, new SingleContinuousPSpace([N21, new NormalDistribution([Rational.of(21n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])]))), add(new RandomSymbol(M22, new SingleContinuousPSpace([M22, new NormalDistribution([Rational.of(4n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])])), new RandomSymbol(N22, new SingleContinuousPSpace([N22, new NormalDistribution([Rational.of(22n, 1n, { gcd: 1n }), Rational.of(1n, 1n, { gcd: 1n })])])))]]))]).doit())).toBe('Matrix([[12, 14], [24, 26]])');
  });
  it("VarianceMatrix(X)", () => {
    const [X, k] = symbols('X k');
    expect(sympyStr(VarianceMatrix(new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))))).toBe('VarianceMatrix(X)');
  });
  it("VarianceMatrix(X).shape", () => {
    const k = new Sym('k');
    const v1 = k;
    expect(sympyMatches([v1, v1], '(k, k)')).toBe(true);
  });
  it("VarianceMatrix(A*X).expand()", () => {
    const [k, X] = symbols('k X');
    expect(sympyStr(new VarianceMatrixNode([MatMul(new MatrixSymbol('A', k, k), new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([])))]).expand())).toBe('A*VarianceMatrix(X)*A.T');
  });
  it("VarianceMatrix(A*X + B*Y).expand()", () => {
    const [k, X, Y] = symbols('k X Y');
    expect(sympyStr(new VarianceMatrixNode([MatAdd(MatMul(new MatrixSymbol('A', k, k), new RandomMatrixSymbol(X, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))), MatMul(new MatrixSymbol('B', k, k), new RandomMatrixSymbol(Y, k, Rational.of(1n, 1n, { gcd: 1n }), new PSpace([]))))]).expand())).toBe('2*A*CrossCovarianceMatrix(X, Y)*B.T + A*VarianceMatrix(X)*A.T + B*VarianceMatrix(Y)*B.T');
  });
});
